 const ordered=[...rows].sort((a,b)=>{const av=Number(a[v]),bv=Number(b[v]);return (Number.isFinite(bv)?bv:-Infinity)-(Number.isFinite(av)?av:-Infinity)}),a=ordered.slice(0,10),other=ordered.slice(10),max=Math.max(1,...ordered.map(x=>Math.abs(Number(x[v])||0)));
