function donut(rows){let total=rows.reduce((s,r)=>s+Number(r.value||r.count||0),0),i=0,col=['#527b89','#84aba7','#c4a77e','#b78f83','#a3acbd','#b7c0a2'];let stops=rows.map((r,j)=>{let prev=i;i+=(Number(r.value??r.count)||0)/Math.max(total,1)*100;return `${col[j%col.length]} ${prev}% ${i}%`}).join(',');return `<div class="e8-donut-layout"><div class="e8-donut" style="background:conic-gradient(${stops||'#dee8e8 0% 100%'})"><div><small>合计</small><strong>${n(total,0)}</strong></div></div><div class="e8-donut-labels">${rows.map((r,j)=>`<div><i style="background:${col[j%col.length]}"></i><span>${e(r.label||r.id)}</span><b>${total?p((Number(r.value??r.count)||0)/total*100):'—'}</b></div>`).join('')}</div></div>`}
function plot(rows,{x='period',y='spend',target=null,series2=null}={}){if(rows.length<2)return '<p class="e8-note">需要至少两个不同期间的数据才能显示趋势</p>';let vs=rows.flatMap(r=>[Number(r[y])||0,...(series2?[Number(r[series2])||0]:[])]),min=Math.min(0,...vs),max=Math.max(target||0,1,...vs),wid=700,hei=205,l=40,r=670,t=20,b=168;const xx=i=>l+(r-l)*i/(rows.length-1),yy=v=>b-(Number(v)-min)/Math.max(1,max-min)*(b-t);let line=k=>rows.map((r,i)=>`${xx(i)},${yy(r[k]||0)}`).join(' ');return `<svg class="e8-svg" viewBox="0 0 700 205" role="img" aria-label="${e(y)} 趋势图"><line x1="40" x2="670" y1="168" y2="168" stroke="#d6e1e0"/>${target!==null?`<line x1="40" x2="670" y1="${yy(target)}" y2="${yy(target)}" stroke="#bb8b74" stroke-dasharray="5 5"/>`:''}<polyline points="${line(y)}" fill="none" stroke="#457d8e" stroke-width="3"/>${series2?`<polyline points="${line(series2)}" fill="none" stroke="#b18f6b" stroke-width="2"/>`:''}${rows.map((r,i)=>`<circle cx="${xx(i)}" cy="${yy(r[y])}" r="3.5" fill="#457d8e"><title>${e(r[x])}: ${e(r[y])}</title></circle><text x="${xx(i)}" y="190" text-anchor="middle" font-size="11" fill="#758a91">${e(r[x])}</text>`).join('')}</svg><p class="e8-note">${series2?'蓝色：'+e(y)+' / 金棕色：'+e(series2)+'。':''}${target!==null?'虚线：演示目标值。':''}</p>`}
